// routes/search.tsx
const advancedArraySchema = z.object({
  // Array of objects
  filters: z
    .array(
      z.object({
        field: z.string(),
        operator: z.enum(['eq', 'gt', 'lt', 'contains']),
        value: z.union([z.string(), z.number(), z.boolean()]),
      }),
